package com.bank.spark.model;

import java.math.BigDecimal;
import java.util.Set;

// A Parquet block with the three skipping aids.
public class ParquetBlock {
    private final int id;
    private final BigDecimal minAmount;
    private final BigDecimal maxAmount;
    private final Set<String> typeDictionary;   // distinct txn types in this block
    private final Set<String> bloomTxnIds;        // bloom membership (simplified)

    public ParquetBlock(int id, BigDecimal minAmount, BigDecimal maxAmount,
                        Set<String> typeDictionary, Set<String> bloomTxnIds) {
        this.id = id;
        this.minAmount = minAmount;
        this.maxAmount = maxAmount;
        this.typeDictionary = typeDictionary;
        this.bloomTxnIds = bloomTxnIds;
    }

    public int getId() { return id; }
    public BigDecimal getMinAmount() { return minAmount; }
    public BigDecimal getMaxAmount() { return maxAmount; }
    public Set<String> getTypeDictionary() { return typeDictionary; }
    public Set<String> getBloomTxnIds() { return bloomTxnIds; }
}
