package com.bank.spark.service;

import com.bank.spark.model.ParquetBlock;

import java.math.BigDecimal;

// Decides whether a block can be skipped by each mechanism.
public class BlockSkipper {

    // Min/max: skip if the block's max is below the "greater than" threshold.
    public boolean skipByMinMax(ParquetBlock b, BigDecimal greaterThan) {
        return b.getMaxAmount().compareTo(greaterThan) <= 0;
    }

    // Dictionary: skip if the equality value is absent from the dictionary.
    public boolean skipByDictionary(ParquetBlock b, String txnType) {
        return !b.getTypeDictionary().contains(txnType);
    }

    // Bloom: skip if "definitely not present" (never a false negative).
    public boolean skipByBloom(ParquetBlock b, String txnId) {
        return !b.getBloomTxnIds().contains(txnId);  // simplified: definite absence
    }
}
