package com.bank.spark;

import com.bank.spark.model.ParquetBlock;
import com.bank.spark.service.BlockSkipper;

import java.math.BigDecimal;
import java.util.List;
import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ParquetSkippingDemo {

    private static final Logger log = Logger.getLogger(ParquetSkippingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BlockSkipper skipper = new BlockSkipper();

        // Four blocks written SORTED by amount — tight non-overlapping ranges.
        List<ParquetBlock> sorted = List.of(
                new ParquetBlock(0, new BigDecimal("0"),      new BigDecimal("25000"),  Set.of("upi", "card"),  Set.of("TX-1","TX-2")),
                new ParquetBlock(1, new BigDecimal("25001"),  new BigDecimal("75000"),  Set.of("upi", "neft"),  Set.of("TX-3","TX-4")),
                new ParquetBlock(2, new BigDecimal("75001"),  new BigDecimal("150000"), Set.of("wire", "neft"), Set.of("TX-5","TX-6")),
                new ParquetBlock(3, new BigDecimal("150001"), new BigDecimal("900000"), Set.of("wire"),         Set.of("TX-7","TX-8"))
        );

        // 1) min/max filter: amount > 100000
        BigDecimal thr = new BigDecimal("100000");
        log.info("Filter amount > 100000 (min/max on SORTED data):");
        for (ParquetBlock b : sorted) {
            boolean skip = skipper.skipByMinMax(b, thr);
            log.info("  block " + b.getId() + " [" + b.getMinAmount() + ".." + b.getMaxAmount() + "] -> " + (skip ? "SKIP" : "READ"));
        }

        // 2) dictionary filter: txnType = 'wire'
        log.info("Filter txnType = 'wire' (dictionary filtering):");
        for (ParquetBlock b : sorted) {
            boolean skip = skipper.skipByDictionary(b, "wire");
            log.info("  block " + b.getId() + " dict=" + b.getTypeDictionary() + " -> " + (skip ? "SKIP" : "READ"));
        }

        // 3) bloom filter: txnId = 'TX-6'
        log.info("Filter txnId = 'TX-6' (bloom filter, high cardinality):");
        for (ParquetBlock b : sorted) {
            boolean skip = skipper.skipByBloom(b, "TX-6");
            log.info("  block " + b.getId() + " -> " + (skip ? "SKIP (definitely not present)" : "READ (possibly present)"));
        }

        log.warning("If the data were UNSORTED, every block's min/max would span 0..900000 and NONE could be skipped by min/max.");
    }
}

